const body = $json.body ?? $json;
const data = body.data ?? body;
const key = data.key ?? {};
const messageObject = data.message ?? {};
const messageType = data.messageType ?? body.messageType ?? '';

const remoteJid = key.remoteJidAlt ?? key.remoteJid ?? body.remoteJid ?? body.from ?? body.phone ?? body.sender ?? '';
const remoteJidText = String(remoteJid);
const senderText = String(body.sender ?? data.sender ?? '');
const phoneSource = remoteJidText.includes('@s.whatsapp.net') ? remoteJidText : senderText || remoteJidText;
const phone = phoneSource.replace(/@s\.whatsapp\.net|@g\.us|@lid/g, '').replace(/\D/g, '');

function valueToText(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number') return String(value);
  return '';
}

function firstText(...values) {
  for (const value of values) {
    const text = valueToText(value);
    if (text) return text;
  }
  return '';
}

function getButtonText(message) {
  const buttonResponse = message.buttonsResponseMessage;
  const templateReply = message.templateButtonReplyMessage;
  const listReply = message.listResponseMessage?.singleSelectReply;
  const nativeParams = message.interactiveResponseMessage?.nativeFlowResponseMessage?.paramsJson;

  let nativeText = '';
  if (nativeParams) {
    try {
      const parsed = JSON.parse(nativeParams);
      nativeText = firstText(parsed.id, parsed.button_id, parsed.selectedId, parsed.display_text);
    } catch (error) {}
  }

  return firstText(
    buttonResponse?.selectedButtonId,
    buttonResponse?.selectedDisplayText,
    templateReply?.selectedId,
    templateReply?.selectedDisplayText,
    listReply?.selectedRowId,
    listReply?.title,
    nativeText
  );
}

const mediaMessage =
  messageObject.documentMessage ??
  messageObject.imageMessage ??
  messageObject.videoMessage ??
  messageObject.audioMessage ??
  messageObject.stickerMessage ??
  null;
const hasFile = Boolean(mediaMessage);
const fallbackFileName = messageType ? `${messageType}-${key.id ?? Date.now()}` : `archivo-${key.id ?? Date.now()}`;
const fileName = firstText(mediaMessage?.fileName, mediaMessage?.title, mediaMessage?.caption) || fallbackFileName;
const mimeType = firstText(mediaMessage?.mimetype) || 'application/octet-stream';
const caption = firstText(mediaMessage?.caption);
const buttonText = getButtonText(messageObject);
const message = firstText(
  body.message,
  body.text,
  body.body,
  messageObject.conversation,
  messageObject.extendedTextMessage?.text,
  messageObject.imageMessage?.caption,
  messageObject.videoMessage?.caption,
  messageObject.documentMessage?.caption,
  messageObject.buttonsResponseMessage?.selectedDisplayText,
  messageObject.templateButtonReplyMessage?.selectedDisplayText,
  buttonText
);

const fromMe = key.fromMe === true || data.fromMe === true || body.fromMe === true;
const isGroup = remoteJidText.includes('@g.us') || remoteJidText.toLowerCase().includes('group') || phone.length > 15;

const normalized = message
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const isSystemEcho =
  fromMe &&
  (
    (normalized.startsWith('hola ') && (normalized.includes('recordamos') || normalized.includes('tu cita') || normalized.includes('su cita'))) ||
    normalized.startsWith('gracias ') ||
    normalized.startsWith('claro ') ||
    normalized.startsWith('entendido ') ||
    normalized.startsWith('listo ') ||
    normalized.startsWith('ese horario ') ||
    normalized.includes('estos son algunos espacios disponibles') ||
    normalized.includes('estas son las opciones mas cercanas') ||
    normalized.includes('si hay disponibilidad') ||
    normalized.includes('no tengo disponibilidad') ||
    normalized.includes('lo mas cercano que encontre') ||
    normalized.includes('puede elegir una opcion') ||
    normalized.includes('responde con el numero de la opcion') ||
    normalized.includes('no pude identificar') ||
    normalized.includes('fecha y hora que enviaste ya pasaron') ||
    normalized.includes('no encontre horarios disponibles') ||
    normalized.includes('registramos tu nueva cita') ||
    normalized.includes('esta cita esta pendiente')
  );

let skip = false;
let skipReason = null;

if (isGroup) {
  skip = true;
  skipReason = 'IGNORED_GROUP_MESSAGE';
} else if (isSystemEcho) {
  skip = true;
  skipReason = 'IGNORED_SYSTEM_ECHO';
} else if (!phone || (!message && !hasFile)) {
  skip = true;
  skipReason = 'IGNORED_EMPTY_MESSAGE';
}

return [{
  json: {
    phone,
    message,
    fromMe,
    remoteJid: remoteJidText,
    skip,
    skipReason,
    hasFile,
    messageId: key.id ?? '',
    instance: body.instance ?? data.instance ?? '',
    serverUrl: body.server_url ?? body.serverUrl ?? '',
    apiKey: body.apikey ?? body.apiKey ?? '',
    fileName,
    mimeType,
    caption
  }
}];

const original = $('Normalizar mensaje').first().json;

let agent = null;
const raw = $json.output ?? $json.text ?? $json.response ?? $json;

if (typeof raw === 'string' && raw.trim()) {
  let cleaned = raw.trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```[a-zA-Z]*\s*/, '').replace(/```$/, '').trim();
  }
  try {
    agent = JSON.parse(cleaned);
  } catch (error) {
    agent = null;
  }
} else if (raw && typeof raw === 'object' && raw.intent) {
  agent = raw;
}

if (agent && typeof agent === 'object') {
  agent = Object.fromEntries(
    Object.entries(agent).filter(([, value]) => value !== null && value !== undefined && value !== '')
  );
}

return [{
  json: {
    phone: original.phone,
    message: original.message,
    agent
  }
}];

