const original = $('Normalizar mensaje').first().json;
const result = $json ?? {};
const reply = Array.isArray(result.replies) ? result.replies[0] : null;

if (!reply?.message || !reply?.to) {
  return [{
    json: {
      shouldSend: false,
      reason: 'NO_REPLY_FROM_SYSTEM',
      systemResult: result
    }
  }];
}

return [{
  json: {
    shouldSend: true,
    phone: String(reply.to).replace(/\D/g, ''),
    clientName: reply.clientName,
    appointmentTitle: reply.appointmentTitle,
    appointmentStartsAt: reply.appointmentStartsAt,
    action: result.action,
    customerMessage: original.message,
    systemReply: reply.message,
    systemResult: result
  }
}];

const prepared = $('Preparar redaccion IA').first().json;
const raw = $json.output ?? $json.text ?? $json.response ?? '';
const text = typeof raw === 'string' && raw.trim() ? raw.trim() : prepared.systemReply;

if (!prepared.phone || !text) {
  throw new Error('Faltan numero o texto para enviar WhatsApp');
}

return [{
  json: {
    evolutionPayload: {
      number: prepared.phone,
      text
    }
  }
}];

const original = $('Normalizar mensaje').first().json;
const response = $json ?? {};
const data =
  response.base64 ??
  response.data ??
  response.file ??
  response.media ??
  response?.result?.base64 ??
  response?.message?.base64 ??
  response?.response?.base64 ??
  '';

if (!data) {
  throw new Error('Evolution API no devolvio base64 para el archivo');
}

return [{
  json: {
    phone: original.phone,
    fileName: original.fileName || 'archivo',
    mimeType: original.mimeType || 'application/octet-stream',
    caption: original.caption || original.message || '',
    data
  }
}];
